import { registerSW as registerViteSW } from 'virtual:pwa-register'

/**
 * Registers the PWA service worker (generated by vite-plugin-pwa).
 *
 * registerType is 'autoUpdate', but a page already controlled by an older
 * service worker keeps running the cached bundle until it is replaced. When a
 * new worker takes control we reload once so users always get the latest
 * build instead of being stuck on a stale (potentially broken) version.
 */
export function registerSW() {
  if (!import.meta.env.PROD) return
  if (typeof navigator === 'undefined' || !('serviceWorker' in navigator)) return

  try {
    let refreshing = false
    // On the very first install there is no controller yet; claiming control
    // is not an update, so it must not trigger a reload.
    let hadController = Boolean(navigator.serviceWorker.controller)

    navigator.serviceWorker.addEventListener('controllerchange', () => {
      if (!hadController) {
        hadController = true
        return
      }
      if (refreshing) return
      refreshing = true
      window.location.reload()
    })

    let updateSW = () => Promise.resolve(false)

    updateSW = registerViteSW({
      immediate: true,
      onNeedRefresh() {
        // autoUpdate: activate the waiting worker immediately.
        updateSW(true)
      },
      onOfflineReady() {
        // App shell is cached and available offline
      },
    })

    // Re-check for a new deployment when the app regains focus/visibility.
    const checkForUpdate = () => {
      navigator.serviceWorker
        .getRegistration()
        .then((registration) => registration?.update())
        .catch(() => {})
    }

    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') checkForUpdate()
    })
    window.addEventListener('focus', checkForUpdate)
  } catch {
    // Service worker registration is optional — ignore failures
  }
}
